const ejecutado = (n) => { try { return $(n).isExecuted; } catch (e) { return false; } };

const startData = $('Start').first().json || {};
const hotelConfig = startData.hotelConfig || {};

// Fuente 1: fila de cache de hoy en Supabase (HTTP devuelve una fila = un item)
const fila = $('Buscar Cache Clima').first()?.json;
const filaCache = Array.isArray(fila) ? fila[0] : fila;
// Fuente 2: llamada en vivo a Open-Meteo (solo existe si hubo cache miss)
const httpClima = ejecutado('Obtener Clima') ? $('Obtener Clima').first()?.json : null;

let rawClima = {};
if (filaCache?.data?.daily) {
  rawClima = filaCache.data;
} else if (httpClima?.daily) {
  rawClima = httpClima;
}

const climaData = rawClima.daily || {};
let climaPorFecha = {};
let usando_clima_antiguo = false;
let advertenciaClima = null;

if (climaData.time && Array.isArray(climaData.time)) {
  climaData.time.forEach((fecha, i) => {
    climaPorFecha[fecha] = {
      temp_max: climaData.temperature_2m_max?.[i] ?? null,
      temp_min: climaData.temperature_2m_min?.[i] ?? null,
      precipitacion: climaData.precipitation_sum?.[i] ?? null
    };
  });
} else {
  usando_clima_antiguo = true;
  advertenciaClima = 'Datos de clima en vivo no disponibles.';
}

return [{
  json: {
    climaPorFecha,
    usando_clima_antiguo,
    advertenciaClima,
    latitude: hotelConfig.ubicacion?.lat ?? 42.1221,
    longitude: hotelConfig.ubicacion?.lon ?? -8.8488,
    hotelConfig
  }
}];

const climaNode = $('Preparar Clima').first()?.json || {};
const startData = $('Start').first()?.json || {};
const hotelConfig = climaNode.hotelConfig || startData.hotelConfig || {};

// 1. Detección de error HTTP 429 o fallo en la API
const raw = $json;
const esError429 = raw.status === 429 || raw.statusCode === 429 || raw.error?.status === 429;
const inputData = raw.data?.data || raw.data || [];

let hotelesProcesados = [];
let advertencia = null;

// Backup local estático
const BACKUP_COMPSET = [
  { nombre: "Parador de Baiona", rating: 4.6, numResenas: 2150, precio: 145, esTravellerChoice: true },
  { nombre: "Hotel Rompeolas", rating: 4.2, numResenas: 480, precio: 95, esTravellerChoice: false },
  { nombre: "Pazo de Mendoza", rating: 4.5, numResenas: 620, precio: 120, esTravellerChoice: false },
  { nombre: "Hotel Bahia Bayona", rating: 4.1, numResenas: 390, precio: 88, esTravellerChoice: false }
];

if (!esError429 && Array.isArray(inputData) && inputData.length > 0) {
  hotelesProcesados = inputData
    .map(h => ({
      nombre: (h.title || h.nombre || '').replace(/^\d+\.\s*/, ''),
      rating: Number(h.bubbleRating?.rating ?? h.rating ?? null),
      numResenas: h.bubbleRating?.count
        ? Number(String(h.bubbleRating.count).replace(/[(),]/g, ''))
        : (h.numResenas ?? 0),
      precio: Number(h.priceForDisplay ? String(h.priceForDisplay).replace(/[^\d]/g, '') : h.precio) || null,
      esTravellerChoice: h.badge?.type === 'TRAVELLER_CHOICE' || h.esTravellerChoice === true
    }))
    .filter(h => h.rating !== null && !isNaN(h.rating));
} else {
  hotelesProcesados = BACKUP_COMPSET;
  advertencia = "Límite de API alcanzado (Error 429). Se están utilizando datos de respaldo (backup).";
}

// 2. Métricas
const ratingMedio = hotelesProcesados.length
  ? Number((hotelesProcesados.reduce((acc, h) => acc + h.rating, 0) / hotelesProcesados.length).toFixed(2))
  : null;

const hotelesConPrecio = hotelesProcesados.filter(h => h.precio !== null);
const precioMedio = hotelesConPrecio.length
  ? Number((hotelesConPrecio.reduce((acc, h) => acc + h.precio, 0) / hotelesConPrecio.length).toFixed(2))
  : null;

const competenciaResumen = {
  hoteles: hotelesProcesados,
  ratingMedioZona: ratingMedio,
  precioMedioZona: precioMedio,
  numCompetidores: hotelesProcesados.length,
  es_backup: esError429 || !inputData.length,
  nota: esError429 || !inputData.length
    ? "⚠️ Datos de respaldo (backup local) por límite en API externa (429)."
    : "Datos en tiempo real (TripAdvisor API).",
  fecha_datos: new Date().toISOString().split('T')[0]
};

return [{
  json: {
    climaPorFecha: climaNode.climaPorFecha || {},
    competenciaResumen,
    hotelConfig
  }
}];

const compNode = $('Preparar Competencia').first().json || {};
const hotelConfig = compNode.hotelConfig || $('Start').first().json.hotelConfig || {};
const ubicacion = hotelConfig.ubicacion || {};
const codigoComunidad = ubicacion.codigo_region || 'ES-GA';
const diasPeriodo = parseInt(hotelConfig.dias_vista_default || 14);

let itemsHolidays = [];
try {
  itemsHolidays = $input.all().map(i => i.json);
} catch (e) {
  itemsHolidays = [];
}

const festivosSet = new Set();
itemsHolidays.forEach(h => {
  if (h && h.date) {
    if (!h.counties || h.counties.includes(codigoComunidad)) {
      festivosSet.add(h.date);
    }
  }
});

if (Array.isArray(hotelConfig.festivos_locales)) {
  hotelConfig.festivos_locales.forEach(f => festivosSet.add(f));
}

function addDays(date, days) {
  const result = new Date(date);
  result.setUTCDate(result.getUTCDate() + Number(days));
  return result;
}

function toISODate(d) {
  const anio = d.getUTCFullYear();
  const mes = String(d.getUTCMonth() + 1).padStart(2, '0');
  const dia = String(d.getUTCDate()).padStart(2, '0');
  return `${anio}-${mes}-${dia}`;
}

const ahora = new Date();
const fechaBase = new Date(Date.UTC(ahora.getFullYear(), ahora.getMonth(), ahora.getDate()));

const rangosVacaciones = hotelConfig.rangos_vacaciones || [
  { inicio: '-06-22', fin: '-09-10' },
  { inicio: '-12-22', fin: '-01-07' }
];

function esVacacionesEscolares(fechaISO) {
  const mmdd = fechaISO.slice(5);
  return rangosVacaciones.some(r => {
    if (r.inicio > r.fin) {
      return mmdd >= r.inicio.slice(1) || mmdd <= r.fin.slice(1);
    }
    return mmdd >= r.inicio.slice(1) && mmdd <= r.fin.slice(1);
  });
}

const calendarioSerie = Array.from({ length: diasPeriodo }, (_, idx) => {
  const dias_vista = idx + 1;
  const fechaObj = addDays(fechaBase, dias_vista);
  const fechaISO = toISODate(fechaObj);

  return {
    fecha: fechaISO,
    dias_vista,
    es_vacaciones_escolares: esVacacionesEscolares(fechaISO),
    es_festivo: festivosSet.has(fechaISO) ? 1 : 0
  };
});

return [{
  json: {
    calendarioSerie,
    climaPorFecha: compNode.climaPorFecha || {},
    competenciaResumen: compNode.competenciaResumen || null,
    hotelConfig
  }
}];

const vacData = $('Obtener Vacaciones Escolares').first().json || {};
const climaPorFecha = vacData.climaPorFecha || {};
const competenciaResumen = vacData.competenciaResumen || null;
const calendarioSerie = vacData.calendarioSerie || [];
const hotelConfig = vacData.hotelConfig || $('Start').first().json.hotelConfig || {};
const reglasPricing = hotelConfig.reglas_pricing || {};

const factorFestivo = Number(reglasPricing.bonus_festivo ?? 1.10) - 1;
const factorVacaciones = Number(reglasPricing.bonus_vacaciones ?? 1.05) - 1;

const REGLAS_CLIMA = [
  { cumple: (c) => c && c.precipitacion < 1 && c.temp_max > 20, ajuste_pct: 0.05, motivo: 'buen tiempo previsto' },
  { cumple: (c) => c && c.precipitacion > 5, ajuste_pct: -0.05, motivo: 'mal tiempo previsto' }
];

function calcularAjuste(fechaISO, es_vacaciones, es_festivo) {
  let ajuste = 0;
  const motivos = [];

  if (es_vacaciones) {
    ajuste += factorVacaciones;
    motivos.push(`vacaciones escolares (${(factorVacaciones * 100).toFixed(0)}%)`);
  }

  if (es_festivo) {
    ajuste += factorFestivo;
    motivos.push(`festivo (${(factorFestivo * 100).toFixed(0)}%)`);
  }

  const clima = climaPorFecha[fechaISO];
  if (clima) {
    const regla = REGLAS_CLIMA.find(r => r.cumple(clima));
    if (regla) {
      ajuste += regla.ajuste_pct;
      motivos.push(regla.motivo);
    }
  }

  const maxSubida = Number(reglasPricing.techo_ajuste ?? 1.35) - 1;
  const maxBajada = Number(reglasPricing.suelo_ajuste ?? 0.75) - 1;

  ajuste = Math.max(maxBajada, Math.min(maxSubida, ajuste));

  return {
    ajuste_pct: Number(ajuste.toFixed(3)),
    motivo_ajuste: motivos.join(', ') || 'sin ajuste'
  };
}

const contextoExternoSerie = calendarioSerie.map(dia => {
  const { ajuste_pct, motivo_ajuste } = calcularAjuste(dia.fecha, dia.es_vacaciones_escolares, dia.es_festivo);
  return {
    fecha: dia.fecha,
    dias_vista: dia.dias_vista,
    es_vacaciones_escolares: dia.es_vacaciones_escolares,
    es_festivo: dia.es_festivo,
    ajuste_pct,
    motivo_ajuste,
    clima: dia.fecha in climaPorFecha ? climaPorFecha[dia.fecha] : null
  };
});

return [{
  json: {
    contextoExternoSerie,
    competenciaResumen,
    hotelConfig
  }
}];
